#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/*
 * Blocks 802.11 deauthentication / disassociation flood frames.
 *
 * Frame Control byte 0: bits [1:0] protocol version, bits [3:2] type,
 * bits [7:4] subtype. Management frames are type 0; subtype 12 (0xC) is
 * Deauthentication and subtype 10 (0xA) is Disassociation.
 */

#define FC_PROTO_VERSION_MASK 0x03u
#define FC_TYPE_MASK          0x0Cu
#define FC_TYPE_SHIFT         2
#define FC_SUBTYPE_MASK       0xF0u
#define FC_SUBTYPE_SHIFT      4

#define TYPE_MGMT             0x0u
#define SUBTYPE_DISASSOC      0xAu
#define SUBTYPE_DEAUTH        0xCu

bool block_frame(const uint8_t *f, size_t n)
{
    if (f == NULL || n < 2u) {
        return false;
    }

    const uint8_t fc = f[0];

    if ((fc & FC_PROTO_VERSION_MASK) != 0u) {
        return false;
    }

    if (((fc & FC_TYPE_MASK) >> FC_TYPE_SHIFT) != TYPE_MGMT) {
        return false;
    }

    const uint8_t subtype = (uint8_t)((fc & FC_SUBTYPE_MASK) >> FC_SUBTYPE_SHIFT);

